WITH filtered_departments AS (SELECT * FROM departments WHERE budget >= 2339000 AND location IN ('Tokyo', 'Bangkok', 'Chiang Mai')), departments_stats AS (SELECT CASE WHEN budget >= 3385000 THEN 'high' WHEN budget >= 1197000 THEN 'mid' ELSE 'low' END AS budget_bucket, dept_name, MIN(budget) AS min_budget, COUNT(*) AS total_count FROM filtered_departments GROUP BY CASE WHEN budget >= 3385000 THEN 'high' WHEN budget >= 1197000 THEN 'mid' ELSE 'low' END, dept_name) SELECT * FROM departments_stats WHERE total_count < 6 ORDER BY 3 DESC, budget_bucket, dept_name LIMIT 50
